 swimOffset(c:Phaser.GameObjects.Container){return (c as any).swimShift||0;}
 // Original painted beach and jungle. Their outer edges dissolve into the shared ground with
 // noise-shaped feathers so no straight image border is visible anywhere on the island.
 addOriginalArt(){
  const bs=this.textures.get('beach').getSourceImage() as HTMLImageElement;
  const bt=this.textures.createCanvas('beach-blend',bs.width,bs.height)!;
  bt.context.drawImage(bs,0,0);
  const bp=bt.context.getImageData(0,0,bs.width,bs.height);
  // Bottom edge only: the right edge sits under the jungle blend, the top is the world border.
  featherPixels(bp.data,bs.width,bs.height,{bottom:190},11);
  bt.context.putImageData(bp,0,0);bt.refresh();
  this.add.image(0,0,'beach-blend').setOrigin(0).setDisplaySize(1680,945).setDepth(-1000);
  const js=this.textures.get('jungle').getSourceImage() as HTMLImageElement;
  const jt=this.textures.createCanvas('jungle-blend',js.width,js.height)!;
  jt.context.drawImage(js,0,0);
  const jp=jt.context.getImageData(0,0,js.width,js.height);
  // Keep the established linear beach-to-jungle blend on the left.
  const blend=js.width*180/1820;
  for(let y=0;y<js.height;y++)for(let x=0;x<blend;x++)jp.data[(y*js.width+x)*4+3]=Math.floor(255*x/blend);
  // South and east edges open onto the frontier.
  featherPixels(jp.data,js.width,js.height,{bottom:200,right:260},23);
  jt.context.putImageData(jp,0,0);jt.refresh();
  this.add.image(1540,0,'jungle-blend').setOrigin(0).setDisplaySize(1820,945).setDepth(-999);
 }
